NS_IMETHODIMP nsMsgDatabase::AttachHdr(nsIMsgDBHdr* detachedHdr, bool notify,
                                       nsIMsgDBHdr** liveHdr) {
  // Sanity check.
  bool isLive;
  nsresult rv = detachedHdr->GetIsLive(&isLive);
  NS_ENSURE_SUCCESS(rv, rv);
  if (isLive) {
    NS_ERROR("Live nsIMsgDBHdr passed in to AttachHdr()");
    return NS_ERROR_INVALID_ARG;
  }

  // Attach it to the messages table.
  rv = AddNewHdrToDB(detachedHdr, notify);
  NS_ENSURE_SUCCESS(rv, rv);

  // Return the same header that was passed in.
  // That's OK - once detachedHdr is passed in here, the caller won't be
  // using it any more, so we can sneakily recycle it.
  NS_ADDREF(detachedHdr);
  *liveHdr = detachedHdr;
  return NS_OK;
}

NS_IMETHODIMP nsMsgDatabase::CopyHdrFromExistingHdr(nsMsgKey key,
                                                    nsIMsgDBHdr* existingHdr,
                                                    bool addHdrToDB,
                                                    nsIMsgDBHdr** newHdr) {
  nsresult err = NS_OK;

  if (existingHdr) {
    nsMsgHdr* sourceMsgHdr =
        static_cast<nsMsgHdr*>(existingHdr);  // closed system, cast ok
    nsMsgHdr* destMsgHdr = nullptr;
    if (key == nsMsgKey_None) {
      CreateNewHdr((nsIMsgDBHdr**)&destMsgHdr);
    } else {
      CreateNewHdrWithSpecificMsgKey(key, (nsIMsgDBHdr**)&destMsgHdr);
    }
    nsIMdbRow* sourceRow = sourceMsgHdr->GetMDBRow();
    if (!destMsgHdr || !sourceRow) {
      return NS_MSG_MESSAGE_NOT_FOUND;
    }

    nsIMdbRow* destRow = destMsgHdr->GetMDBRow();
    if (!destRow) {
      return NS_ERROR_UNEXPECTED;
    }

    err = destRow->SetRow(GetEnv(), sourceRow);
    if (NS_SUCCEEDED(err)) {
      // we may have gotten the header from a cache - calling SetRow
      // basically invalidates any cached values, so invalidate them.
      destMsgHdr->ClearCachedValues();
      if (addHdrToDB) {
        err = AddNewHdrToDB(destMsgHdr, true);
      }

      if (NS_SUCCEEDED(err) && newHdr) {
        *newHdr = destMsgHdr;
      }
    }
  }
  return err;
